    @Override public Map<String, Object> completion(Map<String, Object> a) throws Exception { String tid = (String) a.get("tid");
        return tx.inTenant(tid, () -> { JsonNode P0 = policy(tid); JsonNode P = P0 == null ? DdWeb.JSON.createObjectNode() : P0; List<Map<String, Object>> out = new java.util.ArrayList<>(); String cj = mapper.selectClasses(tid), mj = mapper.selectMembers(tid); Map<String, Object> o = new LinkedHashMap<>(); o.put("rows", out); if (cj == null) return o; Map<String, String> sidOf = new java.util.HashMap<>(); if (mj != null) for (JsonNode m : arr(parse(mj))) if (m != null && get(m, "id") != null) { String sv = S(get(m, "sid")); if (sv == null || sv.isEmpty()) { JsonNode nn = crypt.memberName(m, tid); sv = nn == null || nn.isNull() ? "" : nn.asText(); } sidOf.put(S(get(m, "id")), sv); } Map<String, Map<String, Integer>> beat = new java.util.HashMap<>(); for (Map<String, Object> r : mapper.selectAllSecs(tid)) beat.computeIfAbsent(r.get("sid") + "|" + r.get("cls"), z -> new LinkedHashMap<>()).put(String.valueOf(r.get("item")), ((Number) r.get("s")).intValue()); Map<String, Map<String, Integer>> best = new java.util.HashMap<>(); for (Map<String, Object> r : mapper.selectBest(tid)) if (r.get("s") != null) best.computeIfAbsent(r.get("sid") + "|" + r.get("cls"), z -> new java.util.HashMap<>()).put(String.valueOf(r.get("item")), ((Number) r.get("s")).intValue());
            String today = java.time.LocalDate.now(java.time.ZoneId.of("Asia/Seoul")).toString();
            for (JsonNode cl : arr(parse(cj))) { if (cl == null || get(cl, "learners") == null || !get(cl, "learners").isArray()) continue; String cid = S(get(cl, "id")); List<String> ex = new java.util.ArrayList<>(); for (JsonNode i : arr(get(cl, "curriculum"))) if (i != null && "exam".equals(S(get(i, "type")))) ex.add(S(get(i, "id"))); for (JsonNode idn : get(cl, "learners")) { String sid = sidOf.get(idn.asText()); if (sid == null || sid.isEmpty()) continue; Map<String, Integer> secs = beat.getOrDefault(sid + "|" + cid, Map.of()); int rate = rateOf(P, cl, secs); Map<String, Integer> bs = best.getOrDefault(sid + "|" + cid, Map.of()), scores = new LinkedHashMap<>(); for (String e : ex) if (bs.containsKey(e)) scores.put(e, bs.get(e)); Integer score = !ex.isEmpty() && scores.size() == ex.size() ? java.util.Collections.min(scores.values()) : null; double need0 = num(get(P, "rate")), pass0 = num(get(P, "pass")); double need = Double.isNaN(need0) ? 0 : need0, pass = Double.isNaN(pass0) ? 0 : pass0; /* v38 정책에 값이 없으면 0(Node +P.rate || 0과 같게) */ boolean moel = S(get(P, "profile")).startsWith("moel-"); Integer att = attRate(cl, idn.asText(), moel, today); boolean done = rate >= need && (ex.isEmpty() || (score != null && score >= pass)) && (!moel || att == null || att >= 80); Map<String, Object> m = new LinkedHashMap<>(); m.put("cls", cid); m.put("sid", sid); m.put("rate", rate); m.put("score", score); m.put("att", att); m.put("done", done); m.put("items", secs); m.put("scores", scores); out.add(m); } } return o; }); }
    /** 서술형 답안 베낀 답안 검사 — Node examCopy와 같은 규칙 */
    @Override public Map<String, Object> examCopy(Map<String, Object> a) throws Exception { String tid = (String) a.get("tid");
        return tx.inTenant(tid, () -> { JsonNode P = policy(tid); double t0 = P == null ? 0 : num(get(P, "copyThr")); int thr = t0 > 0 ? (int) t0 : 80; String cj = mapper.selectClasses(tid); JsonNode classes = cj == null ? null : parse(cj); java.util.TreeMap<String, List<String[]>> G = new java.util.TreeMap<>();
            for (Map<String, Object> r : mapper.selectExamAnswers(tid)) { JsonNode cl = null; if (classes != null && classes.isArray()) for (JsonNode x : classes) if (x != null && String.valueOf(r.get("cls")).equals(S(get(x, "id")))) { cl = x; break; } JsonNode it = null; if (cl != null) for (JsonNode x : arr(get(cl, "curriculum"))) if (x != null && String.valueOf(r.get("item")).equals(S(get(x, "id")))) { it = x; break; } List<JsonNode> Q = it == null ? List.of() : arr(get(it, "qs")); Object ans = r.get("answers"); if (ans == null) continue; JsonNode A = parse(String.valueOf(ans)); if (A == null || !A.isObject()) continue;
                for (var e : (Iterable<Map.Entry<String, JsonNode>>) A::fields) { int k; try { k = Integer.parseInt(e.getKey()); } catch (NumberFormatException x) { continue; } if (k < 0 || k >= Q.size() || Q.get(k) == null || !"essay".equals(S(get(Q.get(k), "t")))) continue; String t = e.getValue() == null || e.getValue().isNull() ? "" : e.getValue().asText(); if (t.trim().length() < 30) continue; G.computeIfAbsent(r.get("cls") + "|" + r.get("item") + "|" + e.getKey(), z -> new java.util.ArrayList<>()).add(new String[] { String.valueOf(r.get("sid")), t }); } }
            List<Map<String, Object>> out = new java.util.ArrayList<>(); for (var e : G.entrySet()) { String[] kk = e.getKey().split("\\|"); List<String[]> L = e.getValue(); for (int i = 0; i < L.size() && i < 500; i++) for (int j = i + 1; j < L.size() && j < 500; j++) { if (L.get(i)[0].equals(L.get(j)[0])) continue; int s = simil(L.get(i)[1], L.get(j)[1]); if (s >= thr) { Map<String, Object> m = new LinkedHashMap<>(); m.put("cls", kk[0]); m.put("item", kk[1]); m.put("q", Integer.parseInt(kk[2])); m.put("a", L.get(i)[0]); m.put("b", L.get(j)[0]); m.put("s", s); out.add(m); } } }
            out.sort((x, y) -> { int c = Integer.compare((int) y.get("s"), (int) x.get("s")); return c != 0 ? c : ("" + x.get("cls") + x.get("item") + x.get("q") + x.get("a") + x.get("b")).compareTo("" + y.get("cls") + y.get("item") + y.get("q") + y.get("a") + y.get("b")); });
            Map<String, Object> o = new LinkedHashMap<>(); o.put("rows", out.size() > 100 ? out.subList(0, 100) : out); o.put("thr", thr); return o; }); }
